using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckFishing.Editor {
public static class FishingAuthoring {
 public const string Folder="TruckFishing",Scene="Assets/TruckFishing/Scenes/TruckFishing.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<FishingMatch>(Folder);foreach(var f in new[]{"Prefabs","Models","Art"})Directory.CreateDirectory("Assets/"+Folder+"/"+f);AssetDatabase.Refresh();m.setup.count=1;m.NormalizeSetup();m.feedback.clips=Sounds();var netPrefab=FishingNetAuthoring.Create();var variants=new[]{Fish("Clownfish","fish",.9f,false),Fish("BluefinTuna","fish",1.45f,false),Fish("BlacktipReefShark","shark",1.3f,true)};var wood=SportsEventAuthoring.Mat(Folder,"Pier warm hardwood",new Color(.68f,.48f,.27f),.16f);wood.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RoadPropsPack/Textures/T_WoodBox_AlbedoTransparency.png");var bed=SportsEventAuthoring.Mat(Folder,"Shallow riverbed",new Color(.41f,.37f,.25f),.05f);var grass=SportsEventAuthoring.Mat(Folder,"Living river banks",new Color(.25f,.4f,.13f),.08f);var physics=SportsEventAuthoring.Contact(Folder,"Dock contact",.65f,.05f);var waterMaterial=WaterMaterial();m.streams=new FishingStream[4];m.streamCameras=new SportsEventCamera[4];m.framing=new SportsCameraFit[4];
 for(int i=0;i<4;i++){var root=new GameObject("Equivalent independent river "+(i+1)).transform;root.position=new Vector3(i*80,0,0);var stream=root.gameObject.AddComponent<FishingStream>();stream.slot=i;stream.fishPrefabs=variants;var net=(GameObject)PrefabUtility.InstantiatePrefab(netPrefab);net.transform.SetParent(root,false);net.transform.localPosition=new Vector3(0,.12f,0);stream.net=net.transform;stream.netBag=net.transform.Find("Net bag");SportsEventAuthoring.Box("Submerged riverbed",new Vector3(0,-.7f,10),new Vector3(16,.3f,24),bed,null,root);for(int z=0;z<23;z++){float bend=Mathf.Sin(z*.28f)*.45f;for(int side=-1;side<=1;side+=2){var bank=SportsEventAuthoring.Box("Curving grassy bank",new Vector3(side*(8.4f+bend),-.05f,z),new Vector3(3.2f,.9f,1.12f),grass,null,root);bank.transform.localRotation=Quaternion.Euler(0,0,side*8);}}var water=new GameObject("River Modeler clear flowing surface");water.transform.SetParent(root,false);water.AddComponent<MeshFilter>().sharedMesh=WaterMesh();water.AddComponent<MeshRenderer>().sharedMaterial=waterMaterial;water.AddComponent<FishingWaterFlow>();SportsEventAuthoring.Box("Wooden fishing pier",new Vector3(0,.0f,-3.7f),new Vector3(15,.4f,3.7f),wood,physics,root);for(int p=0;p<5;p++){SportsEventAuthoring.Box("Pier support piling",new Vector3(-8+p*2.6f,-.55f,-2),new Vector3(.25f,1.5f,.25f),wood,null,root);SportsEventAuthoring.Box("Raised pier plank edging",new Vector3(-8+p*2.6f,.23f,-5.4f),new Vector3(2.4f,.05f,.13f),wood,null,root);}SportsRallyAuthoring.Prop(root,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab",new Vector3(1,.22f,-4),new Vector3(1.5f,.4f,1.3f));var truck=SportsEventAuthoring.Truck(m,Folder,"Stationary fishing truck "+(i+1),root.position+new Vector3(-6.7f,.75f,-3.5f),i);SportsRallyAuthoring.FitTruck(truck);truck.transform.SetParent(root,true);truck.Power(false);truck.body.isKinematic=true;stream.truck=truck;truck.body.constraints=RigidbodyConstraints.FreezeAll;truck.body.rotation=Quaternion.Euler(0,18,0);truck.transform.rotation=truck.body.rotation;stream.splash=Splash(root);Reeds(root,grass);m.streams[i]=stream;var camera=SportsEventAuthoring.Camera("Fixed upstream fishing view "+(i+1));camera.Pose(root.position+new Vector3(0,.3f,10),new Vector3(0,14,-30),58,true);camera.view.orthographic=true;camera.view.farClipPlane=100;camera.view.enabled=i==0;var fit=camera.gameObject.AddComponent<SportsCameraFit>();fit.cameraTarget=camera.view;fit.arenaFit=true;fit.arenaBounds=new Bounds(root.position+new Vector3(0,.3f,10),new Vector3(15,.6f,20));fit.topInset=.18f;fit.bottomInset=.13f;fit.sideInset=.025f;fit.Apply();m.streamCameras[i]=camera;m.framing[i]=fit;}
 FishingPresentationAuthoring.Install(m);m.cameras=new[]{m.streamCameras[0].view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);foreach(var t in m.menus.viewTexts){t.rectTransform.sizeDelta=new Vector2(790,58);t.rectTransform.anchoredPosition=new Vector2(18,-10);t.fontSizeMax=22;t.fontSizeMin=20;t.transform.parent.Find("View data backing").GetComponent<RectTransform>().sizeDelta=new Vector2(810,78);}var legend=SportsUIAuthoring.Text("Fish shapes and controls legend",m.menus.hud.transform,"SMALL FISH 1 LB   ·   TUNA 5 LB   ·   SHARK / X = POISON   ·   MOVE NET LEFT / RIGHT",new Vector2(1820,38),new Vector2(0,-510),21);var rail=SportsUIAuthoring.Rect("Legend contrast rail",m.menus.hud.transform,new Vector2(1880,44),new Vector2(0,-510));rail.AddComponent<UnityEngine.UI.Image>().color=new Color(.005f,.02f,.025f,.9f);rail.transform.SetAsFirstSibling();FishingPreviewAuthoring.Create(m);SportsEventAuthoring.Save(Folder);Validate();}
 static GameObject Fish(string name,string controller,float length,bool poison){string source="Assets/Layer Lab/3D Characters-Fish/Fish/Prefabs/"+name+".prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(source);if(prefab==null)throw new Exception("Required imported fish prefab missing: "+source);var root=new GameObject(poison?"Poison shark X warning":name=="Clownfish"?"Small orange one-pound fish":"Large blue five-pound tuna");var model=(GameObject)PrefabUtility.InstantiatePrefab(prefab);model.transform.SetParent(root.transform,false);var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();var bounds=skin.bounds;float scale=length/bounds.size.z;model.transform.localScale=Vector3.one*scale;model.transform.localPosition=-bounds.center*scale;var material=SportsEventAuthoring.Mat(Folder,"Fish "+name,poison?new Color(.7f,.2f,.85f):Color.white,.45f);material.SetFloat("_Metallic",.05f);material.mainTexture=skin.sharedMaterial.mainTexture;skin.sharedMaterial=material;skin.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;var animator=model.AddComponent<Animator>();animator.runtimeAnimatorController=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Layer Lab/3D Characters-Fish/Fish/Ani/"+controller+".controller");animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;if(animator.runtimeAnimatorController==null)throw new Exception("Imported swimming animation missing");if(poison){var white=SportsEventAuthoring.Mat(Folder,"Poison X enamel",new Color(1,.84f,.94f),.3f);for(int side=-1;side<=1;side+=2){var warning=SportsEventAuthoring.Box("Poison silhouette X",new Vector3(0,.58f,0),new Vector3(.075f,.47f,.075f),white,null,root.transform);warning.transform.localRotation=Quaternion.Euler(55,0,side*45);}}var result=PrefabUtility.SaveAsPrefabAsset(root,"Assets/"+Folder+"/Prefabs/"+root.name+".prefab");UnityEngine.Object.DestroyImmediate(root);return result;}
 static Material WaterMaterial(){var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/RiverModeler/ShaderGraph/Default River.mat");if(source==null)throw new Exception("Installed River Modeler normal map required");var material=SportsEventAuthoring.Mat(Folder,"Clear fishing river",new Color(.055f,.34f,.43f,.38f),.72f);material.shader=Shader.Find("Universal Render Pipeline/Lit");material.SetColor("_BaseColor",new Color(.055f,.34f,.43f,.38f));material.SetFloat("_Surface",1);material.SetFloat("_Blend",0);material.SetFloat("_SrcBlend",(float)UnityEngine.Rendering.BlendMode.SrcAlpha);material.SetFloat("_DstBlend",(float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);material.SetFloat("_ZWrite",0);material.SetFloat("_Cull",0);material.SetFloat("_Metallic",.08f);material.SetTexture("_BumpMap",source.GetTexture("_BumpMap"));material.SetFloat("_BumpScale",.2f);material.mainTextureScale=Vector2.one*.23f;material.shaderKeywords=new[]{"_SURFACE_TYPE_TRANSPARENT","_NORMALMAP"};material.SetColor("_EmissionColor",Color.black);material.globalIlluminationFlags=MaterialGlobalIlluminationFlags.EmissiveIsBlack;material.DisableKeyword("_EMISSION");material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.EnableKeyword("_NORMALMAP");material.renderQueue=3000;material.SetOverrideTag("RenderType","Transparent");material.SetShaderPassEnabled("ShadowCaster",false);EditorUtility.SetDirty(material);return material;}
 static Mesh WaterMesh(){string path="Assets/"+Folder+"/Models/Flowing River Surface.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name="Shallow current surface"};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=new[]{new Vector3(-8.5f,.02f,-2),new Vector3(8.5f,.02f,-2),new Vector3(8.5f,.02f,36),new Vector3(-8.5f,.02f,36)};mesh.normals=Enumerable.Repeat(Vector3.up,4).ToArray();mesh.tangents=Enumerable.Repeat(new Vector4(1,0,0,1),4).ToArray();mesh.colors=new Color[4];mesh.uv=new[]{new Vector2(-8.5f,-2),new Vector2(8.5f,-2),new Vector2(8.5f,36),new Vector2(-8.5f,36)};mesh.SetUVs(2,Enumerable.Repeat(new Vector2(0,-.1f),4).ToArray());mesh.triangles=new[]{0,2,1,0,3,2};mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);return mesh;}
 static void Reeds(Transform root,Material material){var random=new System.Random(501);for(int i=0;i<50;i++){int side=i%2==0?-1:1;float z=(float)random.NextDouble()*22,x=side*(7.1f+(float)random.NextDouble()*.9f);var tuft=new GameObject("Bank reed tuft").transform;tuft.SetParent(root,false);tuft.localPosition=new Vector3(x,.2f,z);for(int k=0;k<3;k++){var reed=SportsEventAuthoring.Box("Reed blade",new Vector3((k-1)*.06f,.35f,0),new Vector3(.035f,.7f,.035f),material,null,tuft);reed.transform.localRotation=Quaternion.Euler(k*9,0,(k-1)*12);}}}
 static ParticleSystem Splash(Transform root){var g=new GameObject("Pooled net catch splash");g.transform.SetParent(root,false);var ps=g.AddComponent<ParticleSystem>();var main=ps.main;main.playOnAwake=false;main.loop=false;main.maxParticles=96;main.startLifetime=.4f;main.startSize=.1f;main.startColor=new Color(.7f,.9f,1,.75f);main.gravityModifier=.35f;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=ps.emission;emission.rateOverTime=0;var material=SportsEventAuthoring.Mat(Folder,"Catch splash droplets",new Color(.7f,.9f,1),.6f);var renderer=ps.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=material;var sphere=GameObject.CreatePrimitive(PrimitiveType.Sphere);renderer.renderMode=ParticleSystemRenderMode.Mesh;renderer.mesh=sphere.GetComponent<MeshFilter>().sharedMesh;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;UnityEngine.Object.DestroyImmediate(sphere);ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);return ps;}
 static AudioClip[] Sounds(){string[] names={"Small bright water plop","Large water scoop","Missed fish ripple","Poison sting","Miss danger pulse","River victory","Fishing result chime"};var clips=new AudioClip[7];for(int n=0;n<7;n++){string path="Assets/"+Folder+"/Audio/"+names[n]+".wav";if(!File.Exists(path)){const int rate=22050;int count=rate/2;var random=new System.Random(310+n);using(var writer=new BinaryWriter(File.Create(path))){writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+count*2);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write(count*2);for(int i=0;i<count;i++){double t=i/(double)rate,envelope=Math.Exp(-t*(n<3?12:6));double frequency=n==0?700-450*t:n==1?400-250*t:n==2?180:n==3?330+110*Math.Sin(t*35):n==4?130:n==5?500+t*800:500-t*650;double tone=Math.Sin(t*frequency*Math.PI*2)*.23+(random.NextDouble()*2-1)*.06;writer.Write((short)(tone*envelope*32767));}}AssetDatabase.ImportAsset(path);}clips[n]=AssetDatabase.LoadAssetAtPath<AudioClip>(path);}return clips;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<FishingMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<FishingMatch>();}if(m==null||m.streams.Length!=4||m.streamCameras.Length!=4)throw new Exception("Four fishing streams/cameras required");foreach(var s in m.streams)if(s.net==null||s.netBag==null||s.fishPrefabs.Length!=3||s.fishPrefabs.Any(x=>x==null))throw new Exception("Fishing net/model references missing");Debug.Log("FISHING_NATIVE_SCENE_VALIDATED");}
}
}
